import React, { FormEvent, ReactNode, useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import { api, Login, Status, usePoll } from "./common";
import "./residency.css";

type RuntimeCapabilities = Record<string, boolean>;
type Accelerator = {
  id:string; node_id:string; vendor:string; model:string; driver?:string;
  vram_used_mb:number; vram_total_mb:number; vram_free_mb:number;
  utilization_pct:number; temperature_c:number; runtime_capabilities?:RuntimeCapabilities;
  power_draw_w?:number;power_limit_w?:number;fan_speed_pct?:number;graphics_clock_mhz?:number;memory_clock_mhz?:number;pcie_generation?:number;pcie_width?:number;performance_state?:string;
};
type SystemTelemetry = {hostname?:string;os?:string;kernel?:string;architecture?:string;cpu_model?:string;cpu_logical?:number;cpu_utilization_pct?:number;load_1?:number;load_5?:number;load_15?:number;ram_total_mb?:number;ram_used_mb?:number;ram_available_mb?:number;swap_total_mb?:number;swap_used_mb?:number;root_disk_total_mb?:number;root_disk_used_mb?:number;root_disk_free_mb?:number;network_addresses?:string[];network_rx_bytes_per_second?:number;network_tx_bytes_per_second?:number;uptime_seconds?:number;sampled_at?:string};
type LogEntry = {timestamp:string;level:string;message:string;attributes?:Record<string,unknown>};
type FleetNode = {
  id:string; name:string; location_class:"local"|"remote"; priority_tier:string; scheduling_state:string;
  desired:{scheduling_enabled:boolean;power:string;desired_pool?:string;auto_reconcile:boolean;power_control_mode:string};
  observed:{connectivity:string;lifecycle:string;power:string;ready?:boolean;last_heartbeat?:string;last_seen_at?:string;agent_version?:string;system?:SystemTelemetry;agent_logs?:LogEntry[]};
  accelerators:Accelerator[]; registered_at:string; updated_at:string;
};
type Target = {
  id:string;adapter:string;accelerator_id?:string;models?:string[];resident_models?:string[];cloud:boolean;
  enabled:boolean;quarantined:boolean;context_limit?:number;slots:number;active?:number;capacity_source?:string;
  capacity_verified:boolean;supports_model_lifecycle:boolean;sharing_enabled:boolean;guarded_exploration:boolean;
  standalone_vram_mb?:number;accelerator_vram_mb?:number;vram_reserve_mb?:number;predicted_slowdown?:number;
  max_slowdown?:number;safety_critical?:boolean;circuit_state?:string;circuit_open_until?:string;circuit_failures?:number;queue_running?:number;queue_pending?:number;
};
type ExecutionPerformance = {duration_ms?:number;ttft_ms?:number;prompt_tokens?:number;completion_tokens?:number;total_tokens?:number;prompt_tps?:number;decode_tps?:number;total_tps?:number;source?:string};
type Workload = {
  request:{id:string;owner_id:string;plane:string;adapter:string;workload_type:string;priority:number;qos?:string;disruption?:string;created_at:string;bounds?:{context_tokens?:number;max_output?:number;frames?:number;width?:number;height?:number;steps?:number}};
  status:string;progress?:number;progress_stage?:string;progress_current?:number;progress_total?:number;error?:string;
  decision?:{blocker?:string;target_id?:string;accelerator_id?:string;estimated_start?:string;estimated_end?:string;confidence?:number};
  plan?:{target_id:string;accelerator_id?:string;model?:string;target_context_limit?:number;target_slots?:number};
  execution?:{external_id?:string;started_at:string;performance?:ExecutionPerformance};
  created_at:string;started_at?:string;updated_at:string;finished_at?:string;execution_attempts?:number;actual_cost_cents?:number;
};
type Residency = {id:string;target_id:string;accelerator_id?:string;model:string;desired_tier:string;observed_tier:string;policy:string;use_count:number;last_used_at?:string;last_error?:string;warm_ram_supported:boolean};
type ResidencyTransition = {id:string;target_id:string;accelerator_id?:string;model:string;from_tier:string;to_tier:string;reason:string;status:"planned"|"running"|"succeeded"|"failed";error?:string;created_at:string;started_at?:string;finished_at?:string};
type AuditEvent = {id:string;type:string;severity:string;timestamp:string;workload_id?:string;actor_id?:string;payload?:unknown};
type Incident = {id:string;severity:string;confidence:number;summary:string;evidence_refs?:string[];status:string;proposal?:unknown;analysis_workload_id?:string;actual_provider?:string;actual_model?:string;updated_at:string};
type Readiness = {mode:string;state_backend:string;artifact_backend:string;release_gate:string;checks:{id:string;label:string;status:"ready"|"partial"|"missing";detail:string}[]};
type Integrations = {integrations:{id:string;label:string;enabled:boolean;ready:boolean;detail:string;secret_bindings?:Record<string,boolean>;allowed?:string[]}[];residency:{enabled:boolean;idle_unload_seconds:number;min_residency_seconds:number;quiet_hours_start?:string;quiet_hours_end?:string};restart_required_fields:string[]};
type Overview = {
  readiness?:Readiness;nodes:FleetNode[];targets:Target[];workloads:Workload[];events:AuditEvent[];
  model_residencies:Residency[];residency_transitions:ResidencyTransition[];
  budget_reservations:{workload_id:string;reserved_cents:number;actual_cents:number;status:string}[];
  scheduler_learning_samples:{id:number;accelerator_id:string;workload_class:string;outcome:string;created_at:string}[];
  interference_profiles:{key:string;accelerator_id:string;runtime_version:string;workload_classes:string[];p95_vram_mb:number;p95_duration_ms:number;predicted_slowdown:number;samples:number;successes:number;rollbacks:number;confidence:number;version:number}[];
  performance_profiles:{id:string;hardware:{gpu_model:string;vram_total_mb:number;host_cpu?:string;host_ram_mb?:number;pcie_info?:string};runtime_name:string;runtime_version:string;model_artifact_id:string;context_profile:number;concurrency:number;prefill:{context_tokens?:number;tok_per_sec:number}[];decode:{concurrency?:number;tok_per_sec:number}[];measured_at:string;sample_count:number;notes?:string[]}[];
  transition_plans:{id:string;workload_id:string;victim_workload_id?:string;reason:string;status:string;error?:string;created_at:string}[];
  node_commands:{id:string;node_id:string;command:string;args?:Record<string,unknown>;issued_by:string;status:string;created_at:string;completed_at?:string;result?:unknown;error?:string}[];
  incidents:Incident[];notifications:{id:string;event_type:string;attempts:number;last_error?:string;delivered_at?:string}[];
};
type TelemetrySnapshot = {timestamp:string;system:SystemTelemetry;accelerators:Accelerator[]};
type TelemetryHistory = {node_id:string;range_minutes:number;samples:TelemetrySnapshot[]};

const emptyOverview:Overview={nodes:[],targets:[],workloads:[],events:[],model_residencies:[],residency_transitions:[],budget_reservations:[],scheduler_learning_samples:[],interference_profiles:[],performance_profiles:[],transition_plans:[],node_commands:[],incidents:[],notifications:[]};
const topTabs=["Overview","Machines","Jobs","Scheduler","Models"] as const;
type TopTab=typeof topTabs[number];
const activeStatuses=new Set(["queued","waiting","admitted","starting","running","cancel_requested","yielding","checkpointing"]);
const terminalStatuses=new Set(["succeeded","failed","cancelled"]);

const gb=(mb:number)=>`${(mb/1024).toFixed(mb>=10240?0:1)} GB`;
const rate=(bytes?:number)=>bytes===undefined?"not reported":bytes>=1e9?`${(bytes/1e9).toFixed(2)} GB/s`:bytes>=1e6?`${(bytes/1e6).toFixed(1)} MB/s`:bytes>=1e3?`${(bytes/1e3).toFixed(1)} KB/s`:`${Math.round(bytes)} B/s`;
const duration=(seconds?:number)=>seconds===undefined?"not reported":seconds>=86400?`${Math.floor(seconds/86400)}d ${Math.floor(seconds%86400/3600)}h`:seconds>=3600?`${Math.floor(seconds/3600)}h ${Math.floor(seconds%3600/60)}m`:`${Math.floor(seconds/60)}m`;
const shortId=(id:string)=>id.length>20?`${id.slice(0,10)}…${id.slice(-6)}`:id;
const when=(value?:string)=>value?new Date(value).toLocaleString():"—";
const pct=(job:Workload)=>Math.max(0,Math.min(100,job.progress_total?Math.round((job.progress_current||0)/job.progress_total*100):Math.round((job.progress||0)*100)));
const nodeTargets=(node:FleetNode,targets:Target[])=>targets.filter(target=>node.accelerators.some(gpu=>gpu.id===target.accelerator_id));
const nodeJobs=(node:FleetNode,jobs:Workload[])=>jobs.filter(job=>node.accelerators.some(gpu=>gpu.id===(job.plan?.accelerator_id||job.decision?.accelerator_id)));
function machineState(node:FleetNode,jobs:Workload[]){
  if(["lost","offline"].includes(node.observed.connectivity))return "OFFLINE";
  if(node.scheduling_state==="draining")return "DRAINING";
  if(node.scheduling_state==="disabled")return "DISABLED";
  if(nodeJobs(node,jobs).some(job=>activeStatuses.has(job.status)))return "BUSY";
  return node.observed.ready?"READY":"ONLINE";
}
function currentAssignment(node:FleetNode,targets:Target[],jobs:Workload[]){
  const active=nodeJobs(node,jobs).filter(job=>activeStatuses.has(job.status));
  if(active.length)return `${active.length} active · ${[...new Set(active.map(job=>job.plan?.model||job.request.workload_type))].join(", ")}`;
  const resident=[...new Set(nodeTargets(node,targets).flatMap(target=>target.resident_models||[]))];
  return resident.length?`${resident.length} resident · ${resident.slice(0,2).join(", ")}`:"No active assignment";
}

function StatCard({label,value,subtext,tone}:{label:string;value:string;subtext?:string;tone?:string}){return <article className={`vg-stat ${tone||""}`}><small>{label}</small><strong>{value}</strong>{subtext&&<span>{subtext}</span>}</article>}
function Metric({label,value}:{label:string;value:string}){return <div className="vg-metric"><small>{label}</small><strong>{value}</strong></div>}
function Empty({children}:{children:ReactNode}){return <div className="vg-empty">{children}</div>}
function Panel({title,kicker,action,children,className=""}:{title:string;kicker?:string;action?:ReactNode;children:ReactNode;className?:string}){return <section className={`vg-panel ${className}`}><div className="vg-panel-head"><div>{kicker&&<small>{kicker}</small>}<h2>{title}</h2></div>{action}</div>{children}</section>}

function MachineCard({node,targets,jobs,onClick}:{node:FleetNode;targets:Target[];jobs:Workload[];onClick:()=>void}){
  const total=node.accelerators.reduce((n,g)=>n+g.vram_total_mb,0), used=node.accelerators.reduce((n,g)=>n+g.vram_used_mb,0);
  const util=node.accelerators.length?Math.round(node.accelerators.reduce((n,g)=>n+g.utilization_pct,0)/node.accelerators.length):0;
  const hot=node.accelerators.length?Math.round(Math.max(...node.accelerators.map(g=>g.temperature_c))):0;
  const routes=nodeTargets(node,targets);
  const state=machineState(node,jobs);
  return <button className="vg-machine-card" onClick={onClick}>
    <div className="vg-machine-head"><div><strong>{node.name}</strong><small>{node.location_class} · {node.desired.power_control_mode} · {node.priority_tier}</small></div><div className={`vg-state ${state.toLowerCase()}`}><b>●</b> {state}<small>{util}% GPU</small></div></div>
    <div className="vg-machine-metrics"><Metric label="VRAM" value={`${gb(used)} / ${gb(total)}`}/><Metric label="GPU load" value={`${util}%`}/><Metric label="Hottest" value={`${hot}°C`}/><Metric label="Routes" value={`${routes.length}`}/></div>
    <div className="vg-bar"><i style={{width:`${total?Math.min(100,used/total*100):0}%`}}/></div>
    <p>{currentAssignment(node,targets,jobs)}</p>
  </button>;
}

function WorkloadCard({job}:{job:Workload}){
  const progress=pct(job), active=activeStatuses.has(job.status);
  return <article className="vg-job">
    <div className="vg-job-head"><div><strong>{job.plan?.model||job.request.workload_type}</strong><small>{job.request.adapter} · {shortId(job.request.id)} · owner {job.request.owner_id}</small></div><Status value={job.status}/></div>
    <div className="vg-job-progress"><i style={{width:`${progress}%`}}/></div>
    <div className="vg-job-facts"><Metric label="Progress" value={`${progress}%`}/><Metric label="Target" value={job.plan?.target_id||job.decision?.target_id||"waiting"}/><Metric label="Priority" value={`P${job.request.priority}`}/><Metric label={active?"Estimated end":"Finished"} value={active?when(job.decision?.estimated_end):when(job.finished_at)}/></div>
    {job.decision?.blocker&&<p className="vg-callout amber">{job.decision.blocker}</p>}{job.error&&<p className="vg-callout red">{job.error}</p>}
  </article>;
}

function OverviewPage({data,onMachine,refresh}:{data:Overview;onMachine:(id:string)=>void;refresh:()=>void}){
  const accelerators=data.nodes.flatMap(node=>node.accelerators), total=accelerators.reduce((n,g)=>n+g.vram_total_mb,0), used=accelerators.reduce((n,g)=>n+g.vram_used_mb,0);
  const online=accelerators.filter(g=>data.nodes.find(n=>n.id===g.node_id)?.observed.connectivity==="connected").length;
  const queue=data.workloads.filter(job=>["queued","waiting","admitted","starting"].includes(job.status));
  const running=data.workloads.filter(job=>activeStatuses.has(job.status));
  const activeOps=data.residency_transitions.filter(row=>["planned","running"].includes(row.status));
  return <>
    <div className="vg-stat-grid"><StatCard label="Active GPUs" value={`${online} / ${accelerators.length}`} subtext={`${data.nodes.filter(n=>n.observed.connectivity==="connected").length} connected nodes`}/><StatCard label="VRAM Used" value={gb(used)} subtext={`of ${gb(total)}`}/><StatCard label="Running" value={`${running.length}`} subtext="unified workloads"/><StatCard label="Queue" value={`${queue.length}`} subtext="durable waiting decisions"/><StatCard label="Model state" value={activeOps.length?"TRANSITIONING":"STEADY"} subtext={activeOps.length?`${activeOps.length} operation${activeOps.length===1?"":"s"}`:`${data.model_residencies.filter(r=>r.observed_tier==="hot_vram").length} hot`}/></div>
    <div className="vg-section-line"><div><h2>Machines</h2><p>One card per physical node. Every route shares the same accelerator inventory.</p></div><button className="vg-quiet" onClick={refresh}>Refresh now</button></div>
    <div className="vg-machine-grid">{data.nodes.map(node=><MachineCard node={node} targets={data.targets} jobs={data.workloads} onClick={()=>onMachine(node.id)} key={node.id}/>)}{!data.nodes.length&&<Empty>No node agents connected.</Empty>}</div>
    <Panel title="Active work" kicker="Unified scheduler" action={<span className="vg-count">{running.length} active</span>}><div className="vg-job-list">{running.slice(0,5).map(job=><WorkloadCard job={job} key={job.request.id}/>)}{!running.length&&<Empty>The fleet is idle. Queued work will appear here as placement begins.</Empty>}</div></Panel>
    <div className="vg-two-col">
      <Panel title="Release readiness" kicker="Deployment truth"><div className="vg-readiness-summary"><Metric label="State" value={data.readiness?.state_backend||"unknown"}/><Metric label="Artifacts" value={data.readiness?.artifact_backend||"unknown"}/><Metric label="Gate" value={data.readiness?.release_gate||"unknown"}/></div><div className="vg-check-list">{data.readiness?.checks.map(check=><article key={check.id}><i className={check.status}/><div><strong>{check.label}</strong><p>{check.detail}</p></div><Status value={check.status}/></article>)}</div></Panel>
      <Panel title="Attention" kicker="Incidents & notifications"><div className="vg-attention"><StatCard label="Open incidents" value={`${data.incidents.filter(i=>i.status!=="closed").length}`}/><StatCard label="Pending delivery" value={`${data.notifications.filter(n=>!n.delivered_at).length}`}/><StatCard label="Failed transitions" value={`${data.residency_transitions.filter(t=>t.status==="failed").length}`}/><StatCard label="Guard rollbacks" value={`${data.scheduler_learning_samples.filter(s=>s.outcome==="rolled_back").length}`}/></div></Panel>
    </div>
  </>;
}

function MachinesPage({data,onMachine}:{data:Overview;onMachine:(id:string)=>void}){
  const [filter,setFilter]=useState<"all"|"local"|"remote">("all");
  const rows=data.nodes.filter(node=>filter==="all"||node.location_class===filter);
  return <><div className="vg-section-line"><div><h1>Machines</h1><p>Physical hosts, scheduling state, and accelerator telemetry.</p></div><div className="vg-pills">{(["all","local","remote"] as const).map(value=><button className={filter===value?"active":""} onClick={()=>setFilter(value)} key={value}>{value} {value==="all"?data.nodes.length:data.nodes.filter(n=>n.location_class===value).length}</button>)}</div></div><div className="vg-machine-grid">{rows.map(node=><MachineCard node={node} targets={data.targets} jobs={data.workloads} onClick={()=>onMachine(node.id)} key={node.id}/>)}</div></>;
}

function JobsPage({jobs}:{jobs:Workload[]}){
  const [filter,setFilter]=useState("active");
  const rows=[...jobs].sort((a,b)=>new Date(b.created_at).getTime()-new Date(a.created_at).getTime()).filter(job=>filter==="all"||(filter==="active"&&activeStatuses.has(job.status))||(filter==="finished"&&terminalStatuses.has(job.status))||job.status===filter);
  return <><div className="vg-section-line"><div><h1>Jobs</h1><p>LLM, ComfyUI, batch, and agent work in the same durable queue.</p></div><div className="vg-pills">{["active","waiting","running","finished","all"].map(value=><button className={filter===value?"active":""} onClick={()=>setFilter(value)} key={value}>{value}</button>)}</div></div><div className="vg-job-list page">{rows.map(job=><WorkloadCard job={job} key={job.request.id}/>)}{!rows.length&&<Empty>No workloads match this filter.</Empty>}</div></>;
}

function TargetPolicyCard({target,refresh}:{target:Target;refresh:()=>void}){
  const initial=()=>({enabled:target.enabled,quarantined:target.quarantined,sharing_enabled:target.sharing_enabled,guarded_exploration:target.guarded_exploration,vram_reserve_mb:target.vram_reserve_mb||0,max_slowdown:target.max_slowdown||0});
  const [policy,setPolicy]=useState(initial),[busy,setBusy]=useState(false),[message,setMessage]=useState("");
  useEffect(()=>setPolicy(initial()),[target]);
  async function save(){setBusy(true);setMessage("");try{await api(`/admin/api/targets/${target.id}/policy`,{method:"PUT",headers:{"Content-Type":"application/json","Idempotency-Key":crypto.randomUUID()},body:JSON.stringify(policy)});setMessage("Policy saved");refresh()}catch(e){setMessage((e as Error).message)}finally{setBusy(false)}}
  return <article className="vg-policy"><div className="vg-card-head"><div><strong>{target.id}</strong><small>{target.adapter} · {target.accelerator_id||"virtual provider"}</small></div><Status value={target.enabled?"enabled":"disabled"}/></div><div className="vg-four"><Metric label="Context" value={target.context_limit?.toLocaleString()||"unknown"}/><Metric label="Slots" value={`${target.active||0} / ${target.slots}`}/><Metric label="Envelope" value={`${target.standalone_vram_mb||0} MB`}/><Metric label="Capacity" value={target.capacity_verified?"verified":"configured"}/></div><div className="vg-model-chips">{target.models?.map(model=><span className={target.resident_models?.includes(model)?"hot":""} key={model}>{model}<small>{target.resident_models?.includes(model)?"VRAM":"loadable"}</small></span>)}</div><div className="vg-policy-form"><label><input type="checkbox" checked={policy.enabled} onChange={e=>setPolicy({...policy,enabled:e.target.checked})}/>Enabled</label><label><input type="checkbox" checked={policy.quarantined} onChange={e=>setPolicy({...policy,quarantined:e.target.checked})}/>Quarantined</label><label><input type="checkbox" checked={policy.sharing_enabled} onChange={e=>setPolicy({...policy,sharing_enabled:e.target.checked})}/>Adaptive sharing</label><label><input type="checkbox" checked={policy.guarded_exploration} disabled={!policy.sharing_enabled} onChange={e=>setPolicy({...policy,guarded_exploration:e.target.checked})}/>Guarded learning</label><label>VRAM reserve MB<input type="number" min="0" value={policy.vram_reserve_mb} onChange={e=>setPolicy({...policy,vram_reserve_mb:Number(e.target.value)})}/></label><label>Maximum slowdown<input type="number" min="0" step="0.05" value={policy.max_slowdown} onChange={e=>setPolicy({...policy,max_slowdown:Number(e.target.value)})}/></label></div><div className="vg-policy-foot"><span>{target.supports_model_lifecycle?"Cold models can be loaded after safe reclaim.":"Externally managed runtime."}</span><button className="vg-quiet" disabled={busy} onClick={save}>{busy?"Saving…":"Save policy"}</button></div>{message&&<p className={message.includes("saved")?"vg-success":"vg-error"}>{message}</p>}</article>;
}

function IncidentDesk({rows,refresh}:{rows:Incident[];refresh:()=>void}){
  const [summary,setSummary]=useState(""),[severity,setSeverity]=useState("S1"),[busy,setBusy]=useState(false),[error,setError]=useState("");
  async function create(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{await api("/admin/api/incidents",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({summary,severity,confidence:.8,evidence_refs:[]})});setSummary("");refresh()}catch(cause){setError((cause as Error).message)}finally{setBusy(false)}}
  return <Panel title="System-agent incidents" kicker="Observe · verify · propose"><form className="vg-incident-create" onSubmit={create}><select value={severity} onChange={e=>setSeverity(e.target.value)}><option>S0</option><option>S1</option><option>S2</option><option>S3</option><option>S4</option></select><input value={summary} onChange={e=>setSummary(e.target.value)} placeholder="Create incident from operator evidence" required/><button disabled={busy}>Create</button></form>{error&&<p className="vg-error pad">{error}</p>}<div className="vg-incident-list">{rows.map(row=><article key={row.id}><div><span className={`vg-severity ${row.severity}`}>{row.severity}</span><strong>{row.summary}</strong></div><Status value={row.status}/><p>{Math.round(row.confidence*100)}% confidence · {row.evidence_refs?.length||0} evidence refs · {row.actual_model||"local evidence"}</p></article>)}{!rows.length&&<Empty>No open incidents.</Empty>}</div></Panel>;
}

function SchedulerPage({data,integrations,refresh}:{data:Overview;integrations:Integrations;refresh:()=>void}){
  return <><div className="vg-section-line"><div><h1>Scheduler</h1><p>Admission, context-aware routing, sharing safety, fallback, and learning.</p></div><span className="vg-count">{data.targets.filter(t=>t.enabled).length} enabled routes</span></div><div className="vg-stat-grid four"><StatCard label="Learning samples" value={`${data.scheduler_learning_samples.length}`}/><StatCard label="Profiles" value={`${data.interference_profiles.length}`} subtext={`${data.interference_profiles.filter(p=>p.confidence>=.5).length} trusted`}/><StatCard label="Transition plans" value={`${data.transition_plans.length}`}/><StatCard label="Cloud ledger" value={`${data.budget_reservations.reduce((n,r)=>n+(r.status==="settled"?r.actual_cents:r.reserved_cents),0)}¢`}/></div><Panel title="Context-aware routes" kicker="Narrowest eligible profile first"><div className="vg-policy-grid">{data.targets.map(target=><TargetPolicyCard target={target} refresh={refresh} key={target.id}/>)}</div></Panel><div className="vg-two-col"><Panel title="Interference profiles" kicker="Conservative p95 composition"><div className="vg-table">{data.interference_profiles.map(row=><article key={row.key}><div><strong>{row.workload_classes.join(" + ")}</strong><small>{row.accelerator_id} · v{row.version}</small></div><Metric label="p95 VRAM" value={`${row.p95_vram_mb} MB`}/><Metric label="Slowdown" value={`${row.predicted_slowdown.toFixed(2)}×`}/><Metric label="Confidence" value={`${Math.round(row.confidence*100)}%`}/></article>)}{!data.interference_profiles.length&&<Empty>Profiles appear after measured executions.</Empty>}</div></Panel><Panel title="Integrations" kicker="Secrets never displayed"><div className="vg-integration-list">{integrations.integrations.map(item=><article key={item.id}><div><strong>{item.label}</strong><Status value={item.ready?"ready":item.enabled?"partial":"disabled"}/></div><p>{item.detail}</p></article>)}</div><div className="vg-residency-rule"><Metric label="Idle unload" value={`${integrations.residency.idle_unload_seconds}s`}/><Metric label="Min residency" value={`${integrations.residency.min_residency_seconds}s`}/><Metric label="Quiet hours" value={integrations.residency.quiet_hours_start&&integrations.residency.quiet_hours_end?`${integrations.residency.quiet_hours_start}–${integrations.residency.quiet_hours_end}`:"not configured"}/></div></Panel></div><IncidentDesk rows={data.incidents} refresh={refresh}/></>;
}

function TransitionRow({row,history}:{row:ResidencyTransition;history:ResidencyTransition[]}){
  const start=new Date(row.started_at||row.created_at).getTime(),elapsed=Math.max(0,Date.now()-start);
  const samples=history.filter(x=>x.id!==row.id&&x.model===row.model&&x.to_tier===row.to_tier&&x.status==="succeeded"&&x.started_at&&x.finished_at).map(x=>new Date(x.finished_at!).getTime()-new Date(x.started_at!).getTime()).sort((a,b)=>a-b);
  const expected=samples[Math.floor(samples.length/2)]||0,active=["planned","running"].includes(row.status),percent=row.status==="succeeded"?100:active&&expected?Math.min(95,Math.max(3,Math.round(elapsed/expected*100))):0;
  return <article className={`vg-operation ${row.status}`}><div className="vg-card-head"><div><strong>{row.model}</strong><small>{row.from_tier.replaceAll("_"," ")} → {row.to_tier.replaceAll("_"," ")} · {row.accelerator_id||row.target_id}</small></div><Status value={row.status}/></div><div className={`vg-job-progress ${active&&!expected?"indeterminate":""}`}><i style={{width:`${percent}%`}}/></div><p>{active?`${Math.round(elapsed/1000)}s elapsed · ${expected?`${percent}% historical ETA`:"waiting for runtime readiness"}`:`${row.reason.replaceAll("_"," ")} · ${when(row.finished_at)}`}</p>{row.error&&<p className="vg-error">{row.error}</p>}</article>;
}
function ResidencyRow({row,refresh}:{row:Residency;refresh:()=>void}){
  const [policy,setPolicy]=useState(row.policy),[busy,setBusy]=useState(false),[error,setError]=useState("");
  useEffect(()=>setPolicy(row.policy),[row.policy]);
  async function change(tier:string){setBusy(true);setError("");try{await api("/admin/api/residency/transition",{method:"POST",headers:{"Content-Type":"application/json","Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({target_id:row.target_id,model:row.model,desired_tier:tier,policy})});refresh()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  return <article className="vg-residency"><div className="vg-card-head"><div><strong>{row.model}</strong><small>{row.target_id} · {row.accelerator_id||"virtual"}</small></div><Status value={row.observed_tier}/></div><div className="vg-residency-actions"><label>Policy<select value={policy} onChange={e=>setPolicy(e.target.value)}><option value="auto">Auto</option><option value="pinned">Pinned</option><option value="manual">Manual</option><option value="off">Off</option></select></label><button className="vg-quiet" disabled={busy||policy===row.policy} onClick={()=>change(row.observed_tier)}>Apply policy</button><button className="vg-quiet" disabled={busy||row.observed_tier==="hot_vram"} onClick={()=>change("hot_vram")}>Load to VRAM</button>{row.warm_ram_supported&&<button className="vg-quiet" disabled={busy||row.observed_tier==="warm_ram"} onClick={()=>change("warm_ram")}>Offload to RAM</button>}<button className="vg-quiet danger" disabled={busy||row.observed_tier==="cold_disk"} onClick={()=>change("cold_disk")}>Unload</button></div><p>{row.use_count} completed uses · last {when(row.last_used_at)}</p>{(error||row.last_error)&&<p className="vg-error">{error||row.last_error}</p>}</article>;
}
function ModelsPage({data,refresh}:{data:Overview;refresh:()=>void}){
  const operations=[...data.residency_transitions].sort((a,b)=>new Date(b.created_at).getTime()-new Date(a.created_at).getTime());
  return <><div className="vg-section-line"><div><h1>Models</h1><p>Measured residency across VRAM, efficient host RAM, and disk.</p></div><button className="vg-quiet" onClick={refresh}>Refresh</button></div><Panel title="Load & unload status" kicker="Runtime-confirmed transitions" action={<span className="vg-count">{operations.filter(o=>["planned","running"].includes(o.status)).length} active</span>}><div className="vg-operation-list">{operations.slice(0,10).map(row=><TransitionRow row={row} history={operations} key={row.id}/>)}{!operations.length&&<Empty>No model transitions recorded.</Empty>}</div></Panel><Panel title="Residency controls" kicker="VRAM · RAM · disk"><div className="vg-residency-grid">{data.model_residencies.map(row=><ResidencyRow row={row} refresh={refresh} key={row.id}/>)}{!data.model_residencies.length&&<Empty>No lifecycle-capable model routes discovered.</Empty>}</div></Panel></>;
}

function TelemetryChart({snapshots,gpuID,range}:{snapshots:TelemetrySnapshot[];gpuID?:string;range:number}){
  const [hover,setHover]=useState<number|null>(null);
  const width=720,height=260,left=46,right=14,top=12,bottom=30,plotW=width-left-right,plotH=height-top-bottom;
  const end=Date.now(),start=end-range*60_000;
  const points=snapshots.map(sample=>{const gpu=sample.accelerators.find(item=>item.id===gpuID);const system=sample.system||{};return {time:new Date(sample.timestamp).getTime(),util:gpu?.utilization_pct||0,vram:gpu?.vram_total_mb?gpu.vram_used_mb/gpu.vram_total_mb*100:0,temp:gpu?.temperature_c||0,cpu:system.cpu_utilization_pct||0,ram:system.ram_total_mb?(system.ram_used_mb||0)/system.ram_total_mb*100:0}}).filter(point=>point.time>=start);
  const x=(time:number)=>left+Math.max(0,Math.min(1,(time-start)/(end-start)))*plotW;
  const y=(value:number)=>top+(1-Math.max(0,Math.min(100,value))/100)*plotH;
  const path=(key:"util"|"vram"|"temp"|"cpu"|"ram")=>points.map((point,index)=>`${index?"L":"M"}${x(point.time).toFixed(1)},${y(point[key]).toFixed(1)}`).join(" ");
  function move(event:React.MouseEvent<SVGSVGElement>){if(!points.length)return;const rect=event.currentTarget.getBoundingClientRect();const mouse=((event.clientX-rect.left)/rect.width)*width;let nearest=0,distance=Infinity;points.forEach((point,index)=>{const value=Math.abs(x(point.time)-mouse);if(value<distance){distance=value;nearest=index}});setHover(nearest)}
  const selected=hover===null?null:points[hover];
  return <div className="vg-chart"><div className="vg-chart-stage"><svg viewBox={`0 0 ${width} ${height}`} onMouseMove={move} onMouseLeave={()=>setHover(null)} aria-label="Live GPU, memory, temperature and host telemetry">
    <g className="gridlines">{[0,25,50,75,100].map(value=><g key={value}><line x1={left} x2={width-right} y1={y(value)} y2={y(value)}/><text x={left-9} y={y(value)+3}>{value}%</text></g>)}</g>
    <g className="x-axis"><text x={left} y={height-8}>{new Date(start).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}</text><text x={left+plotW/2} y={height-8} textAnchor="middle">{new Date(start+(end-start)/2).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}</text><text x={width-right} y={height-8} textAnchor="end">now</text></g>
    {points.length>1&&<><path className="util" d={path("util")}/><path className="vram" d={path("vram")}/><path className="temp" d={path("temp")}/><path className="cpu" d={path("cpu")}/><path className="ram" d={path("ram")}/></>}
    {selected&&<g className="hover-line"><line x1={x(selected.time)} x2={x(selected.time)} y1={top} y2={top+plotH}/>{(["util","vram","temp","cpu","ram"] as const).map(key=><circle className={key} cx={x(selected.time)} cy={y(selected[key])} r="3" key={key}/>)}</g>}
  </svg>{selected&&<div className="vg-chart-tooltip" style={{left:`${Math.min(78,Math.max(9,x(selected.time)/width*100))}%`}}><strong>{new Date(selected.time).toLocaleTimeString()}</strong><span>GPU <b>{selected.util.toFixed(1)}%</b></span><span>VRAM <b>{selected.vram.toFixed(1)}%</b></span><span>Temperature <b>{selected.temp.toFixed(1)}°C</b></span><span>CPU <b>{selected.cpu.toFixed(1)}%</b></span><span>Host RAM <b>{selected.ram.toFixed(1)}%</b></span></div>}</div>
    <div className="vg-chart-legend"><span className="util">GPU</span><span className="vram">VRAM</span><span className="temp">Temperature</span><span className="cpu">CPU</span><span className="ram">Host RAM</span><small>{points.length} controller samples · {range<60?`${range} minutes`:range===60?"1 hour":range===360?"6 hours":"24 hours"}</small></div>
  </div>;
}

function MachinePage({node,data,onBack,refresh}:{node:FleetNode;data:Overview;onBack:()=>void;refresh:()=>void}){
  const tabs=["Telemetry","Overview","Details","Logs","Jobs","Events"] as const; const [tab,setTab]=useState<typeof tabs[number]>("Telemetry"),[busy,setBusy]=useState(false),[draining,setDraining]=useState(false),[commanding,setCommanding]=useState(false),[error,setError]=useState(""),[notice,setNotice]=useState(""),[range,setRange]=useState(5),[logFilter,setLogFilter]=useState("All");
  const {data:telemetry,error:telemetryError}=usePoll<TelemetryHistory>(`/admin/api/nodes/${node.id}/telemetry?range_minutes=${range}`,{node_id:node.id,range_minutes:range,samples:[]},2000);
  const targets=nodeTargets(node,data.targets),jobs=nodeJobs(node,data.workloads),active=jobs.filter(j=>activeStatuses.has(j.status));
  const gpu=node.accelerators[0],total=node.accelerators.reduce((n,g)=>n+g.vram_total_mb,0),used=node.accelerators.reduce((n,g)=>n+g.vram_used_mb,0),util=node.accelerators.length?Math.round(node.accelerators.reduce((n,g)=>n+g.utilization_pct,0)/node.accelerators.length):0;
  const system=node.observed.system||{};
  const measured=jobs.map(job=>job.execution?.performance).filter((value):value is ExecutionPerformance=>Boolean(value));
  const median=(values:number[])=>{const sorted=values.filter(value=>value>0).sort((a,b)=>a-b);return sorted.length?sorted[Math.floor(sorted.length/2)]:0};
  const profile=[...data.performance_profiles].filter(row=>!gpu||row.hardware.gpu_model===gpu.model).sort((a,b)=>new Date(b.measured_at).getTime()-new Date(a.measured_at).getTime())[0];
  const promptTPS=median(profile?.prefill.map(point=>point.tok_per_sec)||[]),decodeTPS=median(measured.map(row=>row.decode_tps||0))||median(profile?.decode.map(point=>point.tok_per_sec)||[]),totalTPS=median(measured.map(row=>row.total_tps||0)),ttft=median(measured.map(row=>row.ttft_ms||0));
  const fmtTPS=(value:number)=>value?value>=1000?`${(value/1000).toFixed(1)}K`:`${value.toFixed(1)}`:"not measured";
  const eventText=(event:AuditEvent)=>JSON.stringify(event.payload||{}); const relevantEvents=data.events.filter(event=>event.workload_id&&jobs.some(j=>j.request.id===event.workload_id)||eventText(event).includes(node.id)||node.accelerators.some(g=>eventText(event).includes(g.id)));
  const nodeCommands=data.node_commands.filter(command=>command.node_id===node.id).sort((a,b)=>new Date(b.created_at).getTime()-new Date(a.created_at).getTime());
  async function schedule(state:string){setBusy(true);setError("");try{await api(`/admin/api/nodes/${node.id}/scheduling`,{method:"POST",headers:{"Content-Type":"application/json","Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({state})});refresh()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function drain(){setDraining(true);setError("");setNotice("");try{const result=await api<{transition_ids:string[]}>(`/admin/api/nodes/${node.id}/drain`,{method:"POST",headers:{"Content-Type":"application/json","Idempotency-Key":crypto.randomUUID()},body:"{}"});setNotice(`Runtime drained without disabling scheduling · ${result.transition_ids.length} transitions`);refresh()}catch(e){setError((e as Error).message)}finally{setDraining(false)}}
  async function refreshAgent(){setCommanding(true);setError("");setNotice("");try{const result=await api<{id:string;status:string}>(`/admin/api/nodes/${node.id}/commands`,{method:"POST",headers:{"Content-Type":"application/json","Idempotency-Key":crypto.randomUUID()},body:JSON.stringify({command:"refresh_capabilities",ttl_seconds:120})});setNotice(`Signed node command ${shortId(result.id)} ${result.status}`);refresh()}catch(e){setError((e as Error).message)}finally{setCommanding(false)}}
  const acceptsWork=node.scheduling_state==="enabled";
  return <><div className="vg-machine-page-head"><div><button className="vg-back" onClick={onBack}>← Machines</button><h1>{node.name}</h1><p>{node.location_class} · {node.desired.power_control_mode} · {node.priority_tier} · {machineState(node,data.workloads)}</p></div><div><button className="vg-quiet" disabled={commanding} onClick={refreshAgent}>{commanding?"Contacting agent…":"Refresh agent"}</button><button className="vg-quiet" disabled={draining} onClick={drain} title="Unload runtime models and caches without changing scheduler admission">{draining?"Draining runtimes…":"Drain runtimes"}</button><button className={`vg-work-toggle ${acceptsWork?"on":"off"}`} disabled={busy} onClick={()=>schedule(acceptsWork?"disabled":"enabled")}>Use for work: {acceptsWork?"ON":"OFF"}</button></div></div>{error&&<p className="vg-error banner">{error}</p>}{notice&&<p className="vg-success banner">{notice}</p>}<div className="vg-subtabs">{tabs.map(value=><button className={tab===value?"active":""} onClick={()=>setTab(value)} key={value}>{value}</button>)}</div>
  {tab==="Telemetry"&&<>
    <div className="vg-stat-grid six"><StatCard label="GPU utilization" value={`${util}%`} subtext={gpu?.performance_state||"live nvidia-smi"}/><StatCard label="VRAM" value={`${gb(used)} / ${gb(total)}`} subtext={`${total?Math.round(used/total*100):0}% allocated`}/><StatCard label="Prompt TPS" value={fmtTPS(promptTPS)} subtext={profile?`measured profile · ${profile.sample_count} samples`:"runtime has not reported prefill timing"}/><StatCard label="Decode TPS" value={fmtTPS(decodeTPS)} subtext={measured.length?"p50 end-to-end completions":"no completed token sample"}/><StatCard label="Total TPS" value={fmtTPS(totalTPS)} subtext="prompt + completion, end-to-end"/><StatCard label="TTFT p50" value={ttft?`${Math.round(ttft)} ms`:"not measured"} subtext="streaming requests only"/></div>
    <div className="vg-three-col"><Panel title="Inference" kicker="Live runtime routes"><div className="vg-info-rows"><InfoRow label="Active sequences" value={`${targets.reduce((n,t)=>n+(t.active||0),0)} / ${targets.reduce((n,t)=>n+t.slots,0)}`}/><InfoRow label="Runtime queue" value={`${targets.reduce((n,t)=>n+(t.queue_running||0),0)} running · ${targets.reduce((n,t)=>n+(t.queue_pending||0),0)} pending`}/><InfoRow label="Prompt throughput" value={fmtTPS(promptTPS)}/><InfoRow label="Decode throughput" value={fmtTPS(decodeTPS)}/><InfoRow label="TTFT p50" value={ttft?`${Math.round(ttft)} ms`:"not measured"}/><InfoRow label="Resident models" value={`${new Set(targets.flatMap(t=>t.resident_models||[])).size}`}/></div></Panel><Panel title="Host system" kicker="Measured by node agent"><div className="vg-info-rows"><InfoRow label="CPU" value={system.cpu_model||"not reported"}/><InfoRow label="CPU utilization" value={system.cpu_utilization_pct===undefined?"not reported":`${system.cpu_utilization_pct.toFixed(1)}% · ${system.cpu_logical||0} logical`}/><InfoRow label="Host RAM" value={system.ram_total_mb?`${gb(system.ram_used_mb||0)} / ${gb(system.ram_total_mb)}`:"not reported"}/><InfoRow label="RAM available" value={system.ram_available_mb===undefined?"not reported":gb(system.ram_available_mb)}/><InfoRow label="Load average" value={system.load_1===undefined?"not reported":`${system.load_1.toFixed(2)} · ${system.load_5?.toFixed(2)} · ${system.load_15?.toFixed(2)}`}/><InfoRow label="Uptime" value={duration(system.uptime_seconds)}/></div></Panel><Panel title="Network & agent" kicker="Current sample"><div className="vg-info-rows"><InfoRow label="RX" value={rate(system.network_rx_bytes_per_second)}/><InfoRow label="TX" value={rate(system.network_tx_bytes_per_second)}/><InfoRow label="Connectivity" value={node.observed.connectivity}/><InfoRow label="Lifecycle" value={node.observed.lifecycle}/><InfoRow label="Agent version" value={node.observed.agent_version||"unknown"}/><InfoRow label="Last telemetry" value={when(node.observed.last_heartbeat)}/></div></Panel></div>
    <Panel title="VRAM composition" kicker="Current physical allocation"><div className="vg-vram-stack">{node.accelerators.map(g=><div style={{width:`${total?g.vram_used_mb/total*100:0}%`}} title={`${g.model}: ${gb(g.vram_used_mb)} (${g.vram_total_mb?g.vram_used_mb/g.vram_total_mb*100:0}%)`} key={g.id}/>)}</div><div className="vg-four pad">{node.accelerators.map(g=><Metric label={g.model} value={`${gb(g.vram_used_mb)} used · ${g.vram_total_mb?Math.round(g.vram_used_mb/g.vram_total_mb*100):0}%`} key={g.id}/>) }<Metric label="Free" value={gb(Math.max(0,total-used))}/><Metric label="Power" value={gpu?.power_draw_w?`${gpu.power_draw_w.toFixed(1)} / ${gpu.power_limit_w?.toFixed(0)||"?"} W`:"not reported"}/><Metric label="Clocks" value={gpu?.graphics_clock_mhz?`${gpu.graphics_clock_mhz.toFixed(0)} / ${gpu.memory_clock_mhz?.toFixed(0)||"?"} MHz`:"not reported"}/></div></Panel>
    <Panel title="Performance" kicker="Controller-retained telemetry" action={<div className="vg-pills">{[5,15,60,360,1440].map(value=><button className={range===value?"active":""} onClick={()=>setRange(value)} key={value}>{value<60?`${value}m`:value===60?"1h":value===360?"6h":"24h"}</button>)}</div>}><TelemetryChart snapshots={telemetry.samples||[]} gpuID={gpu?.id} range={range}/>{telemetryError&&<p className="vg-error pad">{telemetryError}</p>}</Panel>
  </>}
  {tab==="Overview"&&<div className="vg-two-col"><Panel title="Current state"><div className="vg-info-rows"><InfoRow label="State" value={machineState(node,data.workloads)}/><InfoRow label="Scheduler priority" value={node.priority_tier}/><InfoRow label="Control mode" value={node.desired.power_control_mode}/><InfoRow label="Node control" value={nodeCommands[0]?`${nodeCommands[0].command} · ${nodeCommands[0].status}`:"ready · no commands yet"}/><InfoRow label="Location" value={node.location_class}/><InfoRow label="Power" value={node.observed.power}/></div></Panel><Panel title="Current assignment"><div className="vg-info-rows"><InfoRow label="Pool" value={node.desired.desired_pool||"default"}/><InfoRow label="Logical slots" value={`${targets.reduce((n,t)=>n+t.slots,0)}`}/><InfoRow label="Adapters" value={[...new Set(targets.map(t=>t.adapter))].join(", ")||"none"}/><InfoRow label="Active work" value={`${active.length}`}/><InfoRow label="Auto reconcile" value={node.desired.auto_reconcile?"enabled":"disabled"}/></div></Panel></div>}
  {tab==="Details"&&<div className="vg-two-col">{node.accelerators.map(g=><Panel title={g.model} kicker="Accelerator hardware" key={g.id}><div className="vg-info-rows"><InfoRow label="ID" value={g.id}/><InfoRow label="Vendor" value={g.vendor}/><InfoRow label="VRAM" value={gb(g.vram_total_mb)}/><InfoRow label="Driver" value={g.driver||"not reported"}/><InfoRow label="PCIe link" value={g.pcie_generation?`Gen ${g.pcie_generation} ×${g.pcie_width||"?"}`:"not reported"}/><InfoRow label="Power" value={g.power_draw_w?`${g.power_draw_w.toFixed(1)} / ${g.power_limit_w?.toFixed(1)||"?"} W`:"not reported"}/><InfoRow label="Fan" value={g.fan_speed_pct?`${g.fan_speed_pct.toFixed(0)}%`:"not reported"}/><InfoRow label="Graphics / memory clock" value={g.graphics_clock_mhz?`${g.graphics_clock_mhz.toFixed(0)} / ${g.memory_clock_mhz?.toFixed(0)||"?"} MHz`:"not reported"}/><InfoRow label="Performance state" value={g.performance_state||"not reported"}/><InfoRow label="Temperature" value={`${g.temperature_c}°C`}/></div></Panel>)}<Panel title="Host system" kicker="Operating system"><div className="vg-info-rows"><InfoRow label="Hostname" value={system.hostname||"not reported"}/><InfoRow label="Operating system" value={system.os||"not reported"}/><InfoRow label="Kernel" value={system.kernel||"not reported"}/><InfoRow label="Architecture" value={system.architecture||"not reported"}/><InfoRow label="IP addresses" value={system.network_addresses?.join(", ")||"not reported"}/><InfoRow label="CPU" value={system.cpu_model||"not reported"}/><InfoRow label="Logical CPUs" value={system.cpu_logical?.toString()||"not reported"}/><InfoRow label="Host RAM" value={system.ram_total_mb?gb(system.ram_total_mb):"not reported"}/><InfoRow label="Swap" value={system.swap_total_mb?`${gb(system.swap_used_mb||0)} / ${gb(system.swap_total_mb)}`:"none reported"}/><InfoRow label="Root disk" value={system.root_disk_total_mb?`${gb(system.root_disk_used_mb||0)} / ${gb(system.root_disk_total_mb)} · ${gb(system.root_disk_free_mb||0)} free`:"not reported"}/><InfoRow label="Uptime" value={duration(system.uptime_seconds)}/></div></Panel><Panel title="Software & control"><div className="vg-info-rows"><InfoRow label="Node agent" value={node.observed.agent_version||"unknown"}/><InfoRow label="Adapters" value={[...new Set(targets.map(t=>t.adapter))].join(", ")||"none"}/><InfoRow label="Runtime versions" value={[...new Set(targets.map(t=>t.capacity_source||"unreported"))].join(", ")}/><InfoRow label="Registered" value={when(node.registered_at)}/><InfoRow label="Last seen" value={when(node.observed.last_seen_at)}/><InfoRow label="Scheduling" value={node.scheduling_state}/><InfoRow label="Auto reconcile" value={node.desired.auto_reconcile?"enabled":"disabled"}/></div></Panel>{gpu?.runtime_capabilities&&<Panel title="Runtime capabilities"> <div className="vg-capabilities">{Object.entries(gpu.runtime_capabilities).map(([key,value])=><span className={value?"yes":"no"} key={key}>{key.replaceAll("_"," ")}<b>{value?"yes":"no"}</b></span>)}</div></Panel>}</div>}
  {tab==="Logs"&&<Panel title="Logs" kicker="Node agent output, controller audit, and command results" action={<div className="vg-pills">{["All","Agent","Runtime","Scheduler","Jobs","System","Raw"].map(v=><button className={logFilter===v?"active":""} onClick={()=>setLogFilter(v)} key={v}>{v}</button>)}</div>}><div className={`vg-log ${logFilter==="Raw"?"raw":""}`}>{(node.observed.agent_logs||[]).filter(entry=>logFilter==="All"||logFilter==="Agent"||logFilter==="Raw"||entry.message.toLowerCase().includes(logFilter.toLowerCase())).map((entry,index)=><details open={logFilter==="Raw"} key={`agent-${entry.timestamp}-${index}`}><summary><time>{new Date(entry.timestamp).toLocaleTimeString()}</time><b>{entry.level}</b><span>{entry.message}</span><code>node agent</code></summary><pre>{JSON.stringify(entry,null,2)}</pre></details>)}{relevantEvents.filter(event=>logFilter==="All"||logFilter==="Raw"||event.type.toLowerCase().includes(logFilter.toLowerCase().replace("jobs","workload").replace("system","node"))).map(event=><details open={logFilter==="Raw"} key={event.id}><summary><time>{new Date(event.timestamp).toLocaleTimeString()}</time><b>{event.severity}</b><span>{event.type}</span><code>{event.workload_id||"controller"}</code></summary><pre>{JSON.stringify(event,null,2)}</pre></details>)}{data.node_commands.filter(command=>command.node_id===node.id&&(logFilter==="All"||logFilter==="Agent"||logFilter==="Runtime"||logFilter==="Raw")).map(command=><details open={logFilter==="Raw"} key={command.id}><summary><time>{new Date(command.created_at).toLocaleTimeString()}</time><b>{command.status}</b><span>command · {command.command}</span><code>{command.id}</code></summary><pre>{JSON.stringify(command,null,2)}</pre></details>)}{!(node.observed.agent_logs||[]).length&&!relevantEvents.length&&<Empty>No machine logs recorded.</Empty>}</div></Panel>}
  {tab==="Jobs"&&<div className="vg-job-list page">{jobs.map(job=><WorkloadCard job={job} key={job.request.id}/>)}{!jobs.length&&<Empty>No work has been assigned to this machine.</Empty>}</div>}
  {tab==="Events"&&<Panel title="Machine events"><div className="vg-timeline">{relevantEvents.map(event=><article key={event.id}><time>{new Date(event.timestamp).toLocaleString()}</time><i className={event.severity}/><div><strong>{event.type}</strong><small>{event.workload_id||node.id}</small></div></article>)}{!relevantEvents.length&&<Empty>No machine events recorded.</Empty>}</div></Panel>}</>;
}
function InfoRow({label,value}:{label:string;value:string}){return <div><span>{label}</span><strong>{value}</strong></div>}

function Admin(){
  const [ready,setReady]=useState(false),[topTab,setTopTab]=useState<TopTab>("Overview"),[selected,setSelected]=useState<string|null>(null);
  const {data:raw,error,refresh}=usePoll<Overview>(ready?"/admin/api/overview":null,emptyOverview,2000);
  const {data:integrations}=usePoll<Integrations>(ready?"/admin/api/integrations":null,{integrations:[],residency:{enabled:false,idle_unload_seconds:0,min_residency_seconds:0},restart_required_fields:[]},10000);
  const data=useMemo<Overview>(()=>({...emptyOverview,...raw,nodes:raw.nodes||[],targets:raw.targets||[],workloads:raw.workloads||[],events:raw.events||[],model_residencies:raw.model_residencies||[],residency_transitions:raw.residency_transitions||[],budget_reservations:raw.budget_reservations||[],scheduler_learning_samples:raw.scheduler_learning_samples||[],interference_profiles:raw.interference_profiles||[],performance_profiles:raw.performance_profiles||[],transition_plans:raw.transition_plans||[],node_commands:raw.node_commands||[],incidents:raw.incidents||[],notifications:raw.notifications||[]}),[raw]);
  if(!ready)return <Login kind="admin" onReady={()=>setReady(true)}/>;
  const node=selected?data.nodes.find(n=>n.id===selected):undefined;
  return <div className="vg-admin"><header className="vg-admin-header"><a href="/admin/" className="vg-logo"><span>VG</span><div><strong>VRAM GOVERNOR</strong><small>UNIFIED CONTROL PLANE</small></div></a><nav>{topTabs.map(tab=><button className={!selected&&topTab===tab?"active":""} onClick={()=>{setTopTab(tab);setSelected(null)}} key={tab}>{tab}</button>)}</nav><div className="vg-live"><i className={error?"error":""}/>{error?"TELEMETRY DEGRADED":"CONTROL ONLINE"}</div></header><main className="vg-admin-main">{error&&<p className="vg-error banner">{error}</p>}{node?<MachinePage node={node} data={data} onBack={()=>setSelected(null)} refresh={refresh}/>:<>{topTab==="Overview"&&<OverviewPage data={data} onMachine={setSelected} refresh={refresh}/>} {topTab==="Machines"&&<MachinesPage data={data} onMachine={setSelected}/>} {topTab==="Jobs"&&<JobsPage jobs={data.workloads}/>} {topTab==="Scheduler"&&<SchedulerPage data={data} integrations={integrations} refresh={refresh}/>} {topTab==="Models"&&<ModelsPage data={data} refresh={refresh}/>}</>}</main></div>;
}

createRoot(document.getElementById("root")!).render(<Admin/>);
